console.log("Loadhtml.js: Function running");const targetEl=document.querySelector(".target"),loadSnippet=t=>{fetch(`html${t}.html`).then((t=>{if(t.ok)return t.text()})).then((t=>{targetEl.innerHTML=t}))};window.onload=function(){document.querySelector(".eventsbutton").addEventListener(loadSnippet(1)),document.querySelector(".blogbutton").addEventListener(loadSnippet(2))};